internal object DuaMaiDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_new_moon" to DuaText("नव चाँद देखनाय", "ऐ अल्लाह, ई चाँद हमरा सभ पर आशीर्वाद, विश्वास, सुरक्षा आ इस्लामक संग उठय। (ऐ चाँद,) हमर रब आ अहाँक रब अल्लाह छथि।", "अमावस्या देखलासँ।", "प्रत्येक नव मासक सुन्नत दुआ।"),
        "dua_janaza_adult" to DuaText("जनाज़ा प्रार्थना (वयस्क)", "ऐ अल्लाह, हमर जीवित आ हमर मृत, उपस्थित आ अनुपस्थित, हमर जवान आ हमर वृद्ध, हमर पुरुष आ हमर स्त्रीगणकेँ क्षमा करू। ऐ अल्लाह, हमरा मे सँ जे केओ जीवित रहे, ओकरा इस्लाम पर जीवित राखू, आ हमरा मे सँ जकरा अहाँ मरिवाउ, ओकरा विश्वास पर मरिवाउ।", "अन्तिम संस्कारक नमाज़क तेसर तकबीरक बाद।", "एकटा मृत वयस्क लेल सुन्नत दुआ।"),
        "dua_janaza_child" to DuaText("जनाज़ा प्रार्थना (बच्चा)", "ऐ अल्लाह, ओकरा हमरा सभक लेल अग्रदूत (आ मेजबान) बनाउ, ओकरा हमर सभक लेल पुरस्कार आ खजाना बनाउ आ ओकरा हमर सभक लेल सिफ़ारिशकर्ता बनाउ जकर सिफ़ारिश स्वीकार कयल जायत।", "एकटा बच्चाक अन्त्येष्टि प्रार्थनामे (एकटा लड़कीक लेल'इज'अलहा'कहल जाइत अछि)।", "हनाफी लोकनि द्वारा सुन्ना दुआक अभ्यास कयल जाइत छल।"),
        "dua_mayyit_awf" to DuaText("मृतक लेल विस्तृत दुआ", "ऐ अल्लाह, ओकरा क्षमा करू, ओकरा पर दया करू, ओकरा कल्याण करू आ ओकरा क्षमा करू। हुनकर स्वागत समारोहकेँ सम्मानजनक बनाउ आ हुनकर कब्रकेँ विशाल बनाउ, हुनका पानि, बर्फ आ ओसलासँ धोउ आ ओकरा पापसँ शुद्ध करू जेना एकटा सफेद वस्त्र गन्दगीसँ शुद्ध भऽ जाइत अछि।", "अन्त्येष्टि प्रार्थनामे वा मृतकक लेल।", "अवफ इब्न मलिक (र.) के इच्छा छल जे ओ ओ मृत व्यक्ति रहैत।"),
        "dua_visiting_graves" to DuaText("कब्रसभ पर जा रहल छी", "ऐ ईमानवालो आ मुसलमान लोकनि, अहाँ सभ पर शान्ति होअय। जँ अल्लाह चाहैत छथि तँ हम सभ सेहो अहाँ सभक संग चलि जायत। हम अल्लाह सँ प्रार्थना करैत छी जे हमरा सभक आ अहाँक कल्याण होअय।", "कब्रिस्तानमे प्रवेश करैत समय।", "कब्र पर जयबा सँ मृत्यु आ पराकाक स्मरण होइत अछि।"),
        "dua_closing_eyes" to DuaText("मृतकक आँखि बन्द करैत", "ऐ अल्लाह, क्षमा करू (नाम), मार्गप्राप्त लोक सभक बीच अपन पद बढ़ाउ, जे सभ ओ छोड़ि जाइत छथि, तकरा सभक बीच हुनकर उत्तराधिकारी बनि जाउ। ऐ दुनियामे प्रभु, हमरा सभ केँ क्षमा कऽ दियौक आ हुनका क्षमा कऽ दियौक, हुनकर कब्रकेँ प्रशस्त बना दियौक आ ओकरा इजोत सँ भरि दियौक।", "मृतकक आँखि बन्द करैत समय (हुनकर नामक उल्लेख करैत)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम अबू सलमा (रा.) क लेल ई दुआ बनौलनि।"),
        "dua_condolence" to DuaText("शोक (तज़ियाह)", "निश्चय ही अल्लाह के अछि जे ओ लऽ गेल छलाह आ जे किछु ओ देने छलाह, आ जे किछु हुनका लग अछि, तकरा लेल एकटा निश्चित समय अछि, तेँ धैर्य राखू आ पुरस्कारक आशा राखू।", "एकटा मृत्युक बाद एकटा परिवार के प्रति शोक व्यक्त करैत।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम अपन बेटीकेँ ई सन्देश पठौलनि।"),
        "dua_placing_in_grave" to DuaText("मृतकेँ कब्रमे रखै", "अल्लाह के नाम पर आ अल्लाह के रसूल के मार्ग पर।", "जखन मृतककेँ कब्रमे नीचाँ उतारि देल जाइत अछि।", "दफन करबाक सुन्नत दुआ।"),
        "dua_sneezing" to DuaText("छिक्कनाइ।", "सब प्रशंसा अल्लाह के लेल अछि।-अल्लाह अहाँ पर दया करू।-अल्लाह अहाँक मार्गदर्शन करू आ अहाँक काज ठीक करू।", "छिँकिबा पर श्रोता'यारहमुकल्लाह'कहैत अछि, तखन छिँचिबा वाला उत्तर दैत अछि।", "ई दोसर मुसलमान पर मुसलमानक अधिकारमेसँ एक अछि।"),
        "dua_toilet_enter" to DuaText("शौचालयमे प्रवेश", "अल्लाह के नाम पर। ऐ अल्लाह, हम अशुद्ध जिन्न पुरुष आ स्त्री सँ अहाँक शरण चाहैत छी।", "शौचालयमे प्रवेश करबासँ पहिने बायां पैर लगा कऽ।", "बिस्मिल्लाह जिन्न आ व्यक्तिक बीच एकटा पर्दा बनि जाइत अछि।"),
        "dua_toilet_exit" to DuaText("शौचालय छोड़ते हुए", "(हे अल्लाह) हम अहाँक क्षमा माँगैत छी।", "शौचालयसँ बाहर निकलबाक समय दाहिने पैरसँ।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम शौचालयसँ बाहर निकलबाक समय ई कहलनि।"),
        "dua_thanking" to DuaText("कोनो केँ धन्यवाद दैत छी।", "अल्लाह अहाँ के नीक काज के प्रतिदान दे।", "जखन कोनो व्यक्ति अहाँ पर उपकार करैत अछि।", "जे केओ ई कहैत अछि ओ पूरा आभार व्यक्त करैत अछि।"),
        "dua_love_for_allah" to DuaText("जखन कोनो व्यक्ति कहैत अछि'हम अल्लाहक लेल अहाँ सँ प्रेम करैत छी'।", "ओ (अल्लाह), जकर लेल अहाँ हमरा सँ प्रेम करैत छी, अहाँ सँ प्रेम करू।", "जखन कोनो व्यक्ति कहैत अछि जे'हम अल्लाहक लेल अहाँ सँ प्रेम करैत छी'।", "सुन्नत अल्लाह के लेल प्रेम के जवाब दैत अछि।"),
        "dua_seeing_muslim_smile" to DuaText("नमस्कार (सलाम)", "अहाँ सभ पर शान्ति होअय आ अल्लाहक दया आ हुनकर आशीर्वाद होअय।", "जखन कोनो मुसलमानसँ भेंट होइत अछि।", "पूरा सलाम कहने सँ तीस टा नीक काज होइत अछि।"),
        "dua_dressing" to DuaText("कपड़ा पहिरनाइ", "प्रशंसा अछि अल्लाह के जे हमरा ई कपड़ा पहिरने छथि आ बिना कोनो शक्ति वा शक्ति के हमरा लेल ई प्रदान कयलनि।", "जखन कपड़ा पहिरने छी।", "अतीतक पापक क्षमा करबाक शुभ समाचार।"),
        "dua_rooster_donkey" to DuaText("मुर्गा या गदह के सुननाइ", "ऐ अल्लाह, हम अहाँ सँ अहाँक अनुग्रह (मुर्खा) माँगैत छी। हम शापित (गदहा) शयतान सँ अल्लाह मे शरण चाहैत छी।", "एकटा मुर्गा केँ सुनने पर अल्लाह सँ अनुग्रह माँगैत छी; एकटा गदहक ब्राक सुनने पर शयतान सँ शरण लैत अछि।", "मुर्गा एकटा स्वर्गदूतकेँ देखैत अछि आ गदहा एकटा शैतानकेँ देखैत अछि।"),
        "dua_something_liked" to DuaText("किछु प्रशंसनीय देखनाय (दुष्ट आँखि के खिलाफ)", "अल्लाह जे चाहैत छथि, ओ करू।", "कोनो लोकक कोनो प्रशंसनीय वस्तु देखलाक बाद आशीर्वाद लेल प्रार्थना करू।", "आशीर्वादक लेल प्रार्थना दुष्ट आँखि सँ बचबैत अछि।"),
        "dua_sell_buy_debt_repaid" to DuaText("जखन कोनो ऋण चुकबैत छी", "अल्लाह अहाँक परिवार आ धनमे आशीर्वाद दे।", "ऋण चुकबैत समय ऋणदाताक लेल।", "ऋणक प्रतिफल आभार आ पुनर्भुगतान अछि।"),
        "dua_talbiyah" to DuaText("तालबिया", "हम एतऽ छी, हे अल्लाह, एतऽ छी। एतऽ हम छी, अहाँक कोनो साझीदार नहि अछि, एतऽ हम छी। निश्चित रूप सँ प्रशंसा, आशीर्वाद आ प्रभुत्व अहाँक अछि। अहाँक कोनो साझीदार नहि अछि।", "इहराममे प्रवेश करबाक बाद जोरसँ।", "हज आ उमराहक प्रतीक।"),
        "dua_yamani_hajar" to DuaText("रुकन यामनी आ हजार असवादक बीच", "हे हमर प्रभु, हमरा सभ केँ एहि संसार मे भलाइ आ आख़िरत मे भलाइ प्रदान करू आ आगि के सजा सँ बचाउ।", "तवाफमे, यमनी कोना आ कारी पाथरक बीच।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम तवाफमे एहि स्थान पर ई पाठ कयलनि।"),
        "dua_safa_marwa" to DuaText("सफा आ मारवाह पर", "अल्लाह के अतिरिक्त ककरो पूजा करबाक अधिकार नहि अछि, केवल अल्लाह के बिना, बिना साझीदार। शासन हुनकर अछि आ प्रशंसा हुनकर अछि, आ सब चीज पर हुनकर अधिकार अछि। ककरो पूजा करबाक अधिकार नहि अछि सिवाय केवल अल्लाह के; ओ अपन वादा पूरा कयलनि, अपन सेवक के सहायता कयलनि आ मात्र संघसभ केँ पराजित कयलनि।", "सफा पर चढ़ना आ किबला (तीन बेर) के सामना करब।", "सफा आ मारवाह पर पैगम्बर सल्लल्लाहु अलैहि वसल्लम के दिक्र।"),
        "dua_arafah" to DuaText("अराफाक दिन के सर्वश्रेष्ठ दुआ", "ककरो पूज्य-पूज्य होयबाक अधिकार नहि अछि सिवाय अल्लाह के, मात्र, बिना साझीदारक। शासन हुनकर अछि, प्रशंसा सेहो हुनकर अछि, आ ओ सब चीज पर प्रभुत्व रखैत छथि।", "अराफाक दिन-सबसँ नीक दुआ।", "अराफाक दिनक दुआ सबसँ नीक दुआ होइत अछि आ सबसँ नीक शब्द ई होइत अछि।"),
        "dua_takbeer_tashreeq" to DuaText("तकबीर-ए-तश़्रीक", "अल्लाह सबसँ महान छथि, अल्लाह सबसँ महान छथि। अल्लाह के अतिरिक्त कोनो पूज्य-प्रभु नहि अछि। अल्लाह सबसँ महान छथि, अल्लाह सबसँ महान छथि, आ प्रशंसा अल्लाह के लेल अछि।", "9 धुल-हिज्जाक फजरसँ 13 धुल-हिज्जाक असर धरि प्रत्येक अनिवार्य नमाज़क बाद।", "अली आ इब्न मसूद (रा.) सँ रिपोर्ट कयल गेल-हनाफीक अनुसार वाजिब।"),
        "dua_zamzam" to DuaText("ज़मज़म पी रहल छी।", "ऐ अल्लाह, हम अहाँ सँ लाभप्रद ज्ञान, भरपूर भोजन आ प्रत्येक बीमारीक इलाज माँगैत छी।", "ज़मज़म पीयबा मे अहाँ जे किछु चाहैत छी ओकर लेल दुआ बनाउ।", "ज़मज़म जे किछु लेल पीय जाइत अछि (इब्न माजाह 3062) ओकर लेल अछि।"),
        "dua_q_ma_khalaqta_batila" to DuaText("सृष्टिक पर चिंतन", "हे हमर प्रभु, अहाँ ई सभ व्यर्थ मे नहि बनाओल छी। महिमावान छी अहाँ, तेँ हमरा सभ केँ आगि के सजा सँ बचाउ।", "स्वर्ग आ पृथ्वीक निर्माण पर विचार करय वला सभक दुआ।", "समझदार लोकसभक दुआ (उलुल-अलबाब)।"),
        "dua_q_sami_na_munadiyan" to DuaText("हम सभ सुनि लेलहुँ जे विश्वासक लेल पुकारल गेल अछि।", "हे हमर प्रभु, अपना सभ एक जन केँ विश्वासक लेल पुकारैत सुनलनि जे, \"अपन प्रभु पर विश्वास करू\" आ विश्वास कयलहुँ। हे हमर प्रभु, हमरा सभक पाप क्षमा करी, हमर सभक दुष्कृत्य सभ दूर करी आ धर्मपरायण सभक संग हमरा सभक मृत्यु करा दियौक।", "विश्वास आ धर्मपरायण सभक बीच मरिबाक लेल दुआ।", "क्षमा आ नीक अन्तक लेल दुआ।"),
        "dua_q_atina_ma_waadtana" to DuaText("अहाँ जे वचन देलहुँ, से हमरा दे दियौक।", "ऐ हमर प्रभु, हमरा सभ केँ ओ वचन प्रदान करू जे अहाँ अपना रसूल सभक माध्यमसँ हमरा सभक संग कयलहुँ आ पुनरुत्थानक दिन हमरा सभ केँ अपमानित नहि करू। निश्चय ही अहाँ सभ अपन वचन नहि तोड़ैत छी।", "पुनरुत्थानक दिन अपमानसँ शरण।", "आख़िरत मे सम्मान के तलाश मे।"),
        "dua_q_israfana" to DuaText("हमर अति क्षमा करू।", "हमर प्रभु, हमरा सभक पाप आ हमर काज मे हमर अति क्षमा करू, हमर पैर मजबूत करू आ अविश्वासीक लोक सभक विरुद्ध हमरा सभक सहायता करू।", "पूर्व पैगम्बरक साथी सभक दुआ।", "दृढ़ता आ क्षमाक लेल दुआ।"),
        "dua_q_jamiun_nas" to DuaText("अहाँ मानव जाति के इकट्ठी करब।", "ऐ हमर प्रभु, अहाँ अवश्य एहन दिन मनुष्य सभकेँ इकट्ठी करब जाहि दिन कोनो सन्देह नहि होयत। निश्चय ही अल्लाह अपन वचन नहि तोड़ैत छथि।", "पुनरुत्थानक दिन निश्चितताक पुष्टि करैत अछि।", "ज्ञानमे दृढ़ता सँ आधारित लोकसभक दुआ।"),
        "dua_q_maash_shahidin" to DuaText("हमरा सभ केँ गवाह सभक बीच लिखू।", "हे हमर प्रभु, हम सभ विश्वास कयने छी, तेँ अपना सभ केँ साक्षी सभक बीच लिखि लिअ।", "सत्यकेँ चिन्हैत आ विश्वास करैत लोक सभक दुआ।", "अपन विश्वासक स्वीकारक लेल दुआ।"),
        "dua_q_la_tajalna_zalimin" to DuaText("गलत काज करयवला सभक संग नहि।", "हमर प्रभु, हमरा सभ केँ अधर्मी लोक सभक संग नहि राखू।", "अल-अराफक लोकक दुआ।", "गलत काज करयवला सभक भाग्यसँ शरण।"),
        "dua_q_tawaffana_muslimin" to DuaText("मुसलमानक रूपमे धैर्य आ मृत्यु", "हमर प्रभु, हमरा सभ पर धैर्य राखू आ मुसलमानक रूपमे हमरा सभ केँ मारि दियौक।", "फ़िरऔनक जादूगर सभक दुआ जखन ओ विश्वास करैत छलाह।", "परीक्षणमे धैर्य राखू आ विश्वास पर अन्त करू।"),
        "dua_q_la_tajalna_fitnah" to DuaText("उत्पीड़क लेल मुकदमा नहि अछि।", "हम सभ अल्लाह पर निर्भर छी। हमर प्रभु, हमरा सभ केँ अधर्मी लोक सभक लेल परीक्षा नहि बनाउ आ अपन दयासँ इनकार करय वला लोक सभ सँ बचा लिअ।", "मूसा (ए. एस.) के लोकसभक दुआ।", "उत्पीडन आ उत्पीड़कसँ बचाव लेल दुआ।"),
        "dua_q_nuh_ma_laysa_li" to DuaText("क्षमा लेल नूह (अ. स.) क दुआ", "हे हमर प्रभु, हम अहाँ सँ एहन प्रार्थना करबाक शरण चाहैत छी जकर बारे मे हमरा किछु नहि पता अछि। आ जँ अहाँ हमरा क्षमा नहि करैत छी आ हमरा पर दया नहि करैत छी तँ हम हानि पहुँचयवला सभक बीच मे रहब।", "पैगम्बर नूह (अ. स.) के पश्चातापक दुआ।", "उचित व्यवहारसँ पूछबाक एकटा सबक।"),
        "dua_q_mudkhala_sidq" to DuaText("सत्यक प्रवेश आ निकास", "हे हमर प्रभु, हमरा सत्यक संग प्रवेश कराबय आ सत्यक संग बाहर निकलबऽ दियौक आ हमरा अपन तरफ सँ सहायक अधिकार दियौक।", "कोनो नव काजमे प्रवेश करबासँ पहिने, घर वा स्थान।", "दुआ हिज्राक समय पैगम्बर सल्लल्लाहु अलैहि वसल्लम केँ पढ़बैत छल।"),
        "dua_q_la_tadharni_fardan" to DuaText("ज़कारियाक दुआ (ए. एस.)-हमरा अकेला नहि छोड़ि दियौक।", "हे हमर प्रभु, हमरा छोड़ि नहि दियौक, तँ अहाँ सभ श्रेष्ठ उत्तराधिकारी छी।", "बच्चा चाहैत लोकक लेल।", "एहि दुआक माध्यमसँ अल्लाह याह्या (ए. एस.) प्रदान कयलनि।"),
        "dua_q_munzalan_mubarakan" to DuaText("एकटा धन्य अवतरण स्थान", "हे हमर प्रभु, हमरा कोनो धन्य स्थान पर उतरय दियौक आ अहाँ ओहि सभ मे सबसँ नीक छी जे जमीन पर अनैत छथि।", "जखन कोनो नव घर मे जाइ वा कोनो ठाम रुकय-नूह (ए. एस.) क दुआ।", "नव स्थान पर आशीर्वाद लेल दुआ।"),
        "dua_q_amanna_faghfir" to DuaText("हम विश्वास करैत छी, तेँ हमरा क्षमा करू।", "हे हमर प्रभु, हम सभ विश्वास कयने छी, तेँ हमरा सभ केँ क्षमा कऽ दियौक आ हमरा सभ पर दया करी, आ अहाँ सभ पर सबसँ नीक दयालु छी।", "अल्लाह के नेक सेवकों के दुआ।", "क्षमा आ दयाक लेल एकटा व्यापक दुआ।"),
        "dua_q_isrif_jahannam" to DuaText("नरकक सजा पर रोक लगाउ।", "ऐ हमर प्रभु, हमरा सभ सँ नरकक सजा छोड़ि दियौक, वास्तव मे एकर सजा लगातार रहैत अछि। निश्चय ही ई एकटा दुष्ट बस्ती आ निवास स्थान अछि।", "परम करुणामय ('इबादत-रहमान) क सेवकेंक दुआ।", "नरकसँ शरण लेल कुरानिक दुआ।"),
        "dua_q_hab_li_hukman" to DuaText("इब्राहिम (अ. स.) क दुआ-बुद्धि आ जन्नत", "हे हमर प्रभु, हमरा ज्ञान प्रदान करू आ धार्मिक सभक संग हमरा संग जाउ, बादक पीढ़ीमे हमरा सम्मानित उल्लेख करू, आ हमरा आनन्दा बागक उत्तराधिकारीमे सँ बनाउ।", "विवेक, धार्मिक आ स्वर्गक संग माँगैत।", "इब्राहिम (ए. एस.) क एकटा व्यापक दुआ।"),
    )
}
